/* @lc app=leetcode id=2708 lang=kotlin */ class Solution { fun maxStrength(nums: IntArray): Long = nums.map { it.toLong() }.let { n -> if (n.size == 1) n[0] else n.filter { it != 0L }.let { f -> if (f.isEmpty()) 0L else if (f.size == 1 && f[0] < 0 && n.contains(0L)) 0L else if (f.size == 1 && f[0] < 0) f[0] else f.filter { it < 0 }.sorted().let { negs -> (if (negs.size % 2 != 0) negs.dropLast(1) else negs).let { combined -> (combined + f.filter { it > 0 }).let { all -> if (all.isEmpty()) 0L else all.fold(1L) { acc, x -> acc * x } } } } } } }